-- Fixtures for parity/tax-reports.jsonl. Idempotent: run before every
-- parity pass against the scratch database (never production), from the
-- repository root, after pinning the download fixtures' mtime (their ETag
-- and Last-Modified are derived from it):
--
--   touch -t 202601010000.00 parity/tax-reports-fixture.csv parity/tax-reports-fixture.pdf
--   psql postgres://pg:pg@127.0.0.1:55499/norviq -v dir="$PWD/parity" -f parity/tax-reports-setup.sql
--
-- The ready reports point at those two files by absolute path, so Vapor and
-- v2 stream the same bytes without sharing a storage volume. Reports the
-- POST cases create are generated by Vapor's own poller into its storage;
-- this script deletes their rows, never their files.
--
-- Every id is 7a8d0000-0000-4000-8000-00000000XXXX:
--   00000000000N users (1 free, 2 US Pro, 3 DE Pro, 4 DE free with a 2025
--   tax pack, 5 PT Pro, 6 Pro without a profile), 0000000001NN accounts,
--   0000000002NN instruments, 0000000003NN lots, 0000000004NN positions,
--   0000000005NN transactions, 0000000006NN disposals, 0000000007NN
--   dividends, 000000000dNN profiles, 000000000eNN reports.
-- Everything is in EUR or USD-without-conversion so no case reaches the ECB.

BEGIN;

DELETE FROM tax_reports WHERE user_id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM tax_profiles WHERE user_id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM tax_pack_entitlements WHERE user_id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM usage_counters WHERE user_id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM entitlements WHERE user_id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM dividends WHERE id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM lot_disposals WHERE id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM positions WHERE id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM lots WHERE id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM transactions WHERE id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM accounts WHERE user_id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM users WHERE id::text LIKE '7a8d0000-0000-4000-8000-%';
DELETE FROM instruments WHERE id::text LIKE '7a8d0000-0000-4000-8000-%';

